mod solution;

fn main() {
    let cases = [
    (r#"[[1,0,0],[1,1,0],[0,1,1]]"#, r#"5"#),
    (r#"[[1,0],[0,1]]"#, r#"1"#),
    (r#"
[[1,0],[0,1]]
"#, r#"1"#),
    (r#"  
[[1,0,0],[1,1,0],[0,1,1]]
  "#, r#"5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS grid-flood-fill");
}
